SELECT row_to_json(t) FROM (SELECT id, code, status, name, name_dashboard, name_chemspider, name_iupac, smiles, smiles_dashboard, stdinchi, stdinchikey, pubchem_cid, chemspider_id, dtxid, molecular_formula, cas_number, mass_iso, average_mass, metadata_synonyms::text AS metadata_synonyms, metadata_cas::text AS metadata_cas, metadata_ms_ready::text AS metadata_ms_ready, metadata_general::text AS metadata_general FROM susdat_substances ORDER BY id) t;
